-- =========================================================
-- КОРИСТУВАЧІ ТА ПРОФІЛЬ
-- =========================================================

CREATE TABLE IF NOT EXISTS "users" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "email" VARCHAR(255) NOT NULL UNIQUE,
    "full_name" VARCHAR(255) NOT NULL,
    "nickname" VARCHAR(255) NOT NULL UNIQUE,
    "password_hash" VARCHAR(255) NOT NULL,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "units" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL, -- 'g', 'ml', 'pcs', 'cup'
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "metric_types" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "unit_id" INTEGER,
    "name" VARCHAR(255) NOT NULL, -- 'Weight', 'Neck size'
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "body_metrics" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "metric_type_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL,
    "value" DECIMAL(10,2) NOT NULL,
    "recorded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (value > 0),
    PRIMARY KEY("id")
);
CREATE INDEX "idx_body_metrics_user_date" ON "body_metrics" ("user_id", "recorded_at" DESC);

-- =========================================================
-- ДОВІДНИКИ ТРЕНУВАНЬ
-- =========================================================

CREATE TABLE IF NOT EXISTS "equipments" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    "user_id" INTEGER,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "muscles" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    "image_url" VARCHAR(255),
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "tracking_types" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL, -- 'Reps only', 'Time based', 'Weight & Reps'
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "exercises" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "equipment_id" INTEGER,
    "tracking_type_id" INTEGER,
    "user_id" INTEGER,
    "visibility_type_id" INTEGER NOT NULL DEFAULT 1,
    "name" VARCHAR(255) NOT NULL,
    "description" TEXT,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "exercise_muscles" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "exercise_id" INTEGER NOT NULL,
    "muscle_id" INTEGER NOT NULL,
    "impact_percentage" INTEGER DEFAULT 100,
    "is_primary" BOOLEAN DEFAULT true,
    CHECK (impact_percentage >= 0 AND impact_percentage <= 100),
    PRIMARY KEY("id")
);
CREATE UNIQUE INDEX "idx_unique_exercise_muscle" ON "exercise_muscles" ("exercise_id", "muscle_id");

CREATE TABLE IF NOT EXISTS "visibility_type" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL, -- 'Public', 'Private', 'Friends Only'
    PRIMARY KEY("id")
);

-- =========================================================
-- ТРЕНУВАННЯ (LOGS)
-- =========================================================

CREATE TABLE IF NOT EXISTS "workouts" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "user_id" INTEGER NOT NULL,
    "visibility_type_id" INTEGER NOT NULL DEFAULT 1,
    "name" VARCHAR(255) NOT NULL,
    "status" VARCHAR(50) NOT NULL DEFAULT 'IN_PROGRESS',
    "started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "ended_at" TIMESTAMPTZ,
    "description" TEXT,
    "calories" DECIMAL(10,2) DEFAULT 0.00 CHECK (calories >= 0),
    "avg_heart_rate" INTEGER CHECK (avg_heart_rate > 0),
    "max_heart_rate" INTEGER CHECK (max_heart_rate > 0),
    "rpe" INTEGER CHECK (rpe BETWEEN 1 AND 10),
    "feeling_score" INTEGER CHECK (feeling_score BETWEEN 1 AND 5),
    PRIMARY KEY("id")
);
CREATE INDEX "idx_workouts_user_date" ON "workouts" ("user_id", "started_at" DESC);

CREATE TABLE IF NOT EXISTS "log_exercises" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "workout_id" INTEGER NOT NULL,
    "exercise_id" INTEGER NOT NULL,
    "order" INTEGER NOT NULL,
    "notes" TEXT,
    "rest_time" INTEGER DEFAULT 0 CHECK (rest_time >= 0),
    PRIMARY KEY("id")
);
CREATE INDEX "idx_log_exercises_workout" ON "log_exercises" ("workout_id");

CREATE TABLE IF NOT EXISTS "log_sets" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "log_exercise_id" INTEGER NOT NULL,
    "order" INTEGER NOT NULL,
    "weight" DECIMAL(10,2) DEFAULT 0.00 CHECK (weight >= 0),
    "reps" INTEGER DEFAULT 0 CHECK (reps >= 0),
    "duration" INTEGER DEFAULT 0 CHECK (duration >= 0),
    "distance" DECIMAL(10,2) DEFAULT 0.00 CHECK (distance >= 0),
    "is_completed" BOOLEAN DEFAULT false,
    PRIMARY KEY("id")
);
CREATE INDEX "idx_log_sets_exercise" ON "log_sets" ("log_exercise_id");

-- =========================================================
-- ШАБЛОНИ ТРЕНУВАНЬ
-- =========================================================

CREATE TABLE IF NOT EXISTS "workout_templates" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "visibility_type_id" INTEGER DEFAULT 1,
    "creator_id" INTEGER NOT NULL,
    "name" VARCHAR(255) NOT NULL,
    "description" TEXT,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "template_exercises" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "workout_template_id" INTEGER NOT NULL,
    "exercise_id" INTEGER NOT NULL,
    "order" INTEGER NOT NULL,
    "rest_time" INTEGER DEFAULT 60,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "template_sets" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "template_exercise_id" INTEGER NOT NULL,
    "order" INTEGER NOT NULL,
    "weight" DECIMAL(10,2) DEFAULT 0.00 CHECK (weight >= 0),
    "reps" INTEGER DEFAULT 0 CHECK (reps >= 0),
    "duration" INTEGER DEFAULT 0,
    "distance" DECIMAL(10,2) DEFAULT 0.00,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "user_workout_templates" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "user_id" INTEGER NOT NULL,
    "workout_template_id" INTEGER NOT NULL,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "user_friends" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "user_id" INTEGER NOT NULL,
    "friend_id" INTEGER NOT NULL,
    "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (user_id != friend_id),
    PRIMARY KEY("id")
);
CREATE UNIQUE INDEX "idx_unique_friendship" ON "user_friends" ("user_id", "friend_id");
CREATE INDEX "idx_friend_status" ON "user_friends" ("friend_id", "status");

-- =========================================================
-- ХАРЧУВАННЯ (NUTRITION)
-- =========================================================

CREATE TABLE IF NOT EXISTS "foods" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    "brand" VARCHAR(255),
    "calories" DECIMAL(10,2) NOT NULL DEFAULT 0.00 CHECK (calories >= 0),
    "proteins" DECIMAL(10,2) NOT NULL DEFAULT 0.00 CHECK (proteins >= 0),
    "fats" DECIMAL(10,2) NOT NULL DEFAULT 0.00 CHECK (fats >= 0),
    "carbs" DECIMAL(10,2) NOT NULL DEFAULT 0.00 CHECK (carbs >= 0),
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "meal_types" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL, -- Breakfast, Lunch, Dinner, Snack
    PRIMARY KEY("id")
);

-- ПЛАНУВАННЯ
CREATE TABLE IF NOT EXISTS "meal_plans" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "creator_id" INTEGER NOT NULL,
    "visibility_type_id" INTEGER NOT NULL DEFAULT 1,
    "name" VARCHAR(255) NOT NULL,
    "description" TEXT,
    "total_days" INTEGER DEFAULT 1 CHECK (total_days > 0),
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "plan_days" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "meal_plan_id" INTEGER NOT NULL,
    "day_number" INTEGER NOT NULL CHECK (day_number > 0),
    "notes" TEXT,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "plan_meals" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "plan_day_id" INTEGER NOT NULL,
    "meal_type_id" INTEGER NOT NULL,
    "order" INTEGER NOT NULL,
    "time_suggestion" TIME,
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "plan_meal_items" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "plan_meal_id" INTEGER NOT NULL,
    "food_id" INTEGER NOT NULL,
    "unit_id" INTEGER NOT NULL,
    "amount" DECIMAL(10,2) NOT NULL CHECK (amount > 0),
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "user_meal_plans" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "user_id" INTEGER NOT NULL,
    "meal_plan_id" INTEGER NOT NULL,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "started_at" DATE NOT NULL DEFAULT CURRENT_DATE,
    PRIMARY KEY("id")
);
CREATE UNIQUE INDEX "idx_unique_active_user_plan" ON "user_meal_plans" ("user_id") WHERE is_active = true;

-- ЛОГУВАННЯ (ФАКТ)
CREATE TABLE IF NOT EXISTS "log_meals" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "user_id" INTEGER NOT NULL,
    "meal_type_id" INTEGER,
    "name" VARCHAR(255),
    "original_plan_meal_id" INTEGER, -- Посилання на план, якщо лог зроблено по ньому (Optional)
    "consumed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "day_log_date" DATE NOT NULL DEFAULT CURRENT_DATE,
    PRIMARY KEY("id")
);
CREATE INDEX "idx_log_meals_date" ON "log_meals" ("user_id", "day_log_date");

CREATE TABLE IF NOT EXISTS "log_meal_items" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "log_meal_id" INTEGER NOT NULL,
    "food_id" INTEGER NOT NULL,
    "unit_id" INTEGER NOT NULL,
    "amount" DECIMAL(10,2) NOT NULL CHECK (amount > 0), -- наприклад 2 (штуки)
    "calculated_weight_g" DECIMAL(10,2), -- наприклад 150 (грам), щоб легше рахувати калорії
    PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "water_logs" (
    "id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
    "user_id" INTEGER NOT NULL,
    "amount_ml" INTEGER NOT NULL CHECK (amount_ml > 0),
    "consumed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY("id")
);
CREATE INDEX "idx_water_logs_date" ON "water_logs" ("user_id", "consumed_at");

-- =========================================================
-- FOREIGN KEYS & RELATIONS
-- =========================================================

-- Metrics
ALTER TABLE "body_metrics" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;
ALTER TABLE "body_metrics" ADD FOREIGN KEY("metric_type_id") REFERENCES "metric_types"("id");
ALTER TABLE "metric_types" ADD FOREIGN KEY("unit_id") REFERENCES "units"("id");

-- Exercises & Muscles
ALTER TABLE "exercise_muscles" ADD FOREIGN KEY("exercise_id") REFERENCES "exercises"("id") ON DELETE CASCADE;
ALTER TABLE "exercise_muscles" ADD FOREIGN KEY("muscle_id") REFERENCES "muscles"("id");
ALTER TABLE "exercises" ADD FOREIGN KEY("tracking_type_id") REFERENCES "tracking_types"("id");
ALTER TABLE "exercises" ADD FOREIGN KEY("equipment_id") REFERENCES "equipments"("id");
ALTER TABLE "exercises" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;
ALTER TABLE "exercises" ADD FOREIGN KEY("visibility_type_id") REFERENCES "visibility_type"("id");
ALTER TABLE "equipments" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;

-- Workouts
ALTER TABLE "workouts" ADD FOREIGN KEY("visibility_type_id") REFERENCES "visibility_type"("id");
ALTER TABLE "workouts" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;
ALTER TABLE "log_exercises" ADD FOREIGN KEY("exercise_id") REFERENCES "exercises"("id");
ALTER TABLE "log_exercises" ADD FOREIGN KEY("workout_id") REFERENCES "workouts"("id") ON DELETE CASCADE;
ALTER TABLE "log_sets" ADD FOREIGN KEY("log_exercise_id") REFERENCES "log_exercises"("id") ON DELETE CASCADE;

-- Workout Templates
ALTER TABLE "workout_templates" ADD FOREIGN KEY("visibility_type_id") REFERENCES "visibility_type"("id");
ALTER TABLE "workout_templates" ADD FOREIGN KEY("creator_id") REFERENCES "users"("id") ON DELETE CASCADE;
ALTER TABLE "template_exercises" ADD FOREIGN KEY("workout_template_id") REFERENCES "workout_templates"("id") ON DELETE CASCADE;
ALTER TABLE "template_exercises" ADD FOREIGN KEY("exercise_id") REFERENCES "exercises"("id");
ALTER TABLE "template_sets" ADD FOREIGN KEY("template_exercise_id") REFERENCES "template_exercises"("id") ON DELETE CASCADE;
ALTER TABLE "user_workout_templates" ADD FOREIGN KEY("workout_template_id") REFERENCES "workout_templates"("id") ON DELETE CASCADE;
ALTER TABLE "user_workout_templates" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;

-- Social
ALTER TABLE "user_friends" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;
ALTER TABLE "user_friends" ADD FOREIGN KEY("friend_id") REFERENCES "users"("id") ON DELETE CASCADE;

-- Nutrition Plan
ALTER TABLE "meal_plans" ADD FOREIGN KEY("visibility_type_id") REFERENCES "visibility_type"("id");
ALTER TABLE "meal_plans" ADD FOREIGN KEY("creator_id") REFERENCES "users"("id") ON DELETE NO ACTION; 
ALTER TABLE "plan_days" ADD FOREIGN KEY("meal_plan_id") REFERENCES "meal_plans"("id") ON DELETE CASCADE;
ALTER TABLE "plan_meals" ADD FOREIGN KEY("plan_day_id") REFERENCES "plan_days"("id") ON DELETE CASCADE;
ALTER TABLE "plan_meals" ADD FOREIGN KEY("meal_type_id") REFERENCES "meal_types"("id");
ALTER TABLE "plan_meal_items" ADD FOREIGN KEY("plan_meal_id") REFERENCES "plan_meals"("id") ON DELETE CASCADE;
ALTER TABLE "plan_meal_items" ADD FOREIGN KEY("food_id") REFERENCES "foods"("id");
ALTER TABLE "plan_meal_items" ADD FOREIGN KEY("unit_id") REFERENCES "units"("id");
ALTER TABLE "user_meal_plans" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;
ALTER TABLE "user_meal_plans" ADD FOREIGN KEY("meal_plan_id") REFERENCES "meal_plans"("id") ON DELETE CASCADE;

-- Nutrition Log
ALTER TABLE "log_meals" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;
ALTER TABLE "log_meals" ADD FOREIGN KEY("meal_type_id") REFERENCES "meal_types"("id");
ALTER TABLE "log_meals" ADD FOREIGN KEY("original_plan_meal_id") REFERENCES "plan_meals"("id") ON DELETE SET NULL; -- Якщо план видалять, лог залишиться
ALTER TABLE "log_meal_items" ADD FOREIGN KEY("log_meal_id") REFERENCES "log_meals"("id") ON DELETE CASCADE;
ALTER TABLE "log_meal_items" ADD FOREIGN KEY("food_id") REFERENCES "foods"("id");
ALTER TABLE "log_meal_items" ADD FOREIGN KEY("unit_id") REFERENCES "units"("id");

-- Water
ALTER TABLE "water_logs" ADD FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE;